def fill_symbols(apps, schema_editor):
    """Rows entered in the admin before this migration were keyed by company: copy its symbol
    and spell the fiscal year the way the crawler does (2081/82 -> 2081/2082)."""
    DividendAnnouncement = apps.get_model("market_data", "DividendAnnouncement")
    for row in DividendAnnouncement.objects.select_related("company"):
        if row.company_id:
            row.symbol = row.company.symbol.upper()
        start, _, end = row.fiscal_year.strip().partition("/")
        if start.isdigit() and end.isdigit() and len(end) < len(start):
            row.fiscal_year = f"{start}/{int(start) + 1}"
        row.save(update_fields=["symbol", "fiscal_year"])


